tool_input.content:
[
  {
    "id": "EXP-01",
    "title": "Target distribution characterisation",
    "objective": "Determine the distributional shape of performance_rating and check for subpopulations.",
    "hypotheses": ["H-01"],
    "input_artifacts": ["dataset.csv"],
    "method": {
      "steps": [
        "Load dataset.csv and extract performance_rating column.",
        "Plot histogram with 30 bins overlaid with KDE curve.",
        "Run Shapiro-Wilk normality test; report W statistic and p-value.",
        "Compute skewness and kurtosis.",
        "Optionally run Hartigan dip test for unimodality."
      ],
      "libraries": ["pandas", "matplotlib", "seaborn", "scipy.stats"]
    },
    "expected_outputs": [
      {"type": "plot", "filename": "performance_rating_distribution.png", "description": "Histogram + KDE of performance_rating"},
      {"type": "table", "description": "Distribution statistics: mean, std, skew, kurtosis, Shapiro-Wilk W, p-value"}
    ],
    "validation": {
      "check": "Mean should be approximately 50.0, std approximately 10.0 per profile.",
      "row_count": 800
    }
  },
  {
    "id": "EXP-02",
    "title": "Feature distribution overview",
    "objective": "Visualise marginal distributions for all features to identify anomalies, skew, or unexpected patterns.",
    "hypotheses": [],
    "input_artifacts": ["dataset.csv", "column_summary.csv"],
    "method": {
      "steps": [
        "Load dataset.csv.",
        "For each numeric column, plot histogram + KDE (subplot grid).",
        "For salary_band, plot bar chart of level frequencies.",
        "Flag any features with extreme skew (|skew| > 2) or unexpected ranges."
      ],
      "libraries": ["pandas", "matplotlib", "seaborn"]
    },
    "expected_outputs": [
      {"type": "plot", "filename": "feature_distributions.png", "description": "Grid of histograms for all features"},
      {"type": "plot", "filename": "salary_band_counts.png", "description": "Bar chart of salary_band frequencies"}
    ],
    "validation": {
      "check": "All feature ranges should match column_summary.csv min/max values."
    }
  },
  {
    "id": "EXP-03",
    "title": "Linear correlation analysis",
    "objective": "Compute Pearson correlations between each numeric feature and performance_rating.",
    "hypotheses": ["H-02"],
    "input_artifacts": ["dataset.csv"],
    "method": {
      "steps": [
        "Load dataset; select numeric columns excluding employee_id.",
        "Compute Pearson r and p-value for each feature vs performance_rating using scipy.stats.pearsonr.",
        "Build a full correlation matrix heatmap for all numeric features.",
        "Record all individual p-values for later FDR correction in EXP-11."
      ],
      "libraries": ["pandas", "scipy.stats", "seaborn", "matplotlib"]
    },
    "expected_outputs": [
      {"type": "plot", "filename": "correlation_heatmap.png", "description": "Full pairwise Pearson correlation heatmap"},
      {"type": "table", "description": "Feature, Pearson r, p-value for each feature vs performance_rating"}
    ],
    "validation": {
      "check": "Correlation values must be in [-1, 1]; p-values in [0, 1]. If data is pure noise, expect |r| < 0.1 for most pairs."
    }
  },
  {
    "id": "EXP-04",
    "title": "Nonlinear association detection",
    "objective": "Test for nonlinear relationships using Spearman rank correlation and distance correlation.",
    "hypotheses": ["H-03"],
    "input_artifacts": ["dataset.csv"],
    "method": {
      "steps": [
        "Compute Spearman rho and p-value for each numeric feature vs performance_rating.",
        "Compute distance correlation (dcor library or manual) for each feature vs performance_rating.",
        "Generate scatter plots with LOWESS smoother for each feature vs performance_rating.",
        "Record all p-values for FDR correction in EXP-11."
      ],
      "libraries": ["pandas", "scipy.stats", "matplotlib", "seaborn", "dcor"]
    },
    "expected_outputs": [
      {"type": "plot", "filename": "scatter_matrix_lowess.png", "description": "Scatter plots with LOWESS for each feature vs performance_rating"},
      {"type": "table", "description": "Feature, Spearman rho, p-value, distance correlation for each feature vs performance_rating"}
    ],
    "validation": {
      "check": "If distance correlation is near zero for all features, confirms lack of any (linear or nonlinear) association."
    }
  },
  {
    "id": "EXP-05",
    "title": "Performance rating by salary band",
    "objective": "Test whether performance_rating differs across salary_band groups.",
    "hypotheses": ["H-04"],
    "input_artifacts": ["dataset.csv"],
    "method": {
      "steps": [
        "Group dataset by salary_band; compute group means, medians, and standard deviations for performance_rating.",
        "Run Kruskal-Wallis H-test across groups.",
        "Generate box plots of performance_rating by salary_band.",
        "If Kruskal-Wallis is significant, run post-hoc Dunn test with Bonferroni correction.",
        "Record Kruskal-Wallis p-value for FDR correction in EXP-11."
      ],
      "libraries": ["pandas", "scipy.stats", "seaborn", "matplotlib", "scikit_posthocs"]
    },
    "expected_outputs": [
      {"type": "plot", "filename": "salary_band_boxplot.png", "description": "Box plots of performance_rating by salary_band"},
      {"type": "table", "description": "Group statistics and Kruskal-Wallis H, p-value"}
    ],
    "validation": {
      "check": "Each salary_band group should have at least 100 observations based on profile (top=L5, freq=170)."
    }
  },
  {
    "id": "EXP-06",
    "title": "Multicollinearity assessment",
    "objective": "Check pairwise correlations and VIF among numeric predictors.",
    "hypotheses": ["H-05"],
    "input_artifacts": ["dataset.csv"],
    "method": {
      "steps": [
        "Compute full Pearson correlation matrix for numeric features (excluding employee_id and performance_rating).",
        "Plot annotated heatmap.",
        "Compute VIF for each predictor using statsmodels.",
        "Flag any predictor with VIF > 5 or any pair with |r| > 0.5."
      ],
      "libraries": ["pandas", "statsmodels", "seaborn", "matplotlib"]
    },
    "expected_outputs": [
      {"type": "plot", "filename": "feature_correlation_heatmap.png", "description": "Correlation heatmap of predictors only"},
      {"type": "table", "description": "Feature, VIF value for each predictor"}
    ],
    "validation": {
      "check": "If features are independently generated, expect all VIF near 1.0 and all |r| < 0.1."
    }
  },
  {
    "id": "EXP-07",
    "title": "Linear regression baseline comparison",
    "objective": "Fit OLS regression and compare cross-validated performance to a mean-prediction baseline.",
    "hypotheses": ["H-06"],
    "input_artifacts": ["dataset.csv"],
    "method": {
      "steps": [
        "Define features: all numeric columns except employee_id and performance_rating. Target: performance_rating.",
        "Compute baseline RMSE (std of target) and baseline R-squared (0.0).",
        "Fit OLS linear regression using 5-fold cross-validation.",
        "Record mean CV RMSE and R-squared.",
        "Report OLS F-test p-value from full-sample fit.",
        "Record F-test p-value for FDR correction in EXP-11."
      ],
      "libraries": ["pandas", "sklearn", "statsmodels"]
    },
    "expected_outputs": [
      {"type": "table", "description": "Model, CV RMSE, CV R-squared, F-test p-value"},
      {"type": "plot", "filename": "model_comparison.png", "description": "Bar chart comparing baseline vs OLS vs random forest RMSE and R-squared"}
    ],
    "validation": {
      "check": "Baseline RMSE should be approximately 10.0 (target std). OLS RMSE should be close to or above baseline if no signal."
    }
  },
  {
    "id": "EXP-08",
    "title": "Random forest with permutation test",
    "objective": "Fit a random forest regressor and use a permutation test to assess whether predictive power is genuine.",
    "hypotheses": ["H-06"],
    "input_artifacts": ["dataset.csv"],
    "method": {
      "steps": [
        "Define same features and target as EXP-07.",
        "Fit RandomForestRegressor (100 trees, max_depth=5) with 5-fold CV. Record RMSE and R-squared.",
        "Extract feature importances from full-sample fit.",
        "Run permutation test: shuffle target 100 times, refit 5-fold CV each time, collect null R-squared distribution.",
        "Compute permutation p-value: proportion of null R-squared >= observed R-squared.",
        "Plot histogram of null R-squared distribution with observed value marked.",
        "Record permutation p-value for FDR correction in EXP-11."
      ],
      "libraries": ["pandas", "sklearn"]
    },
    "expected_outputs": [
      {"type": "plot", "filename": "permutation_test.png", "description": "Null R-squared distribution with observed value line"},
      {"type": "plot", "filename": "feature_importance.png", "description": "Bar chart of random forest feature importances"},
      {"type": "table", "description": "RF CV RMSE, R-squared, permutation p-value"}
    ],
    "validation": {
      "check": "Permutation p-value should be > 0.05 if data is pure noise. If p < 0.05, genuine signal may exist."
    }
  },
  {
    "id": "EXP-09",
    "title": "Salary band classification",
    "objective": "Test whether salary_band is predictable from numeric features vs majority-class baseline.",
    "hypotheses": ["H-07"],
    "input_artifacts": ["dataset.csv"],
    "method": {
      "steps": [
        "Define features: all numeric columns except employee_id. Target: salary_band.",
        "Compute majority-class baseline accuracy (max class frequency / 800).",
        "Fit RandomForestClassifier (100 trees) with 5-fold CV. Record accuracy, macro F1.",
        "Generate confusion matrix from cross-validated predictions.",
        "Run binomial test: observed accuracy vs baseline probability.",
        "Record binomial test p-value for FDR correction in EXP-11."
      ],
      "libraries": ["pandas", "sklearn", "scipy.stats", "seaborn", "matplotlib"]
    },
    "expected_outputs": [
      {"type": "plot", "filename": "salary_band_confusion.png", "description": "Confusion matrix heatmap"},
      {"type": "table", "description": "Baseline accuracy, RF accuracy, macro F1, binomial p-value"}
    ],
    "validation": {
      "check": "Baseline accuracy should be approximately 21.25% (170/800). If RF accuracy is close to baseline, salary_band is unpredictable."
    }
  },
  {
    "id": "EXP-10",
    "title": "PCA and cluster analysis",
    "objective": "Search for natural employee segments using dimensionality reduction and clustering.",
    "hypotheses": ["H-08"],
    "input_artifacts": ["dataset.csv"],
    "method": {
      "steps": [
        "Standardize all numeric features (exclude employee_id).",
        "Run PCA; plot scree plot of explained variance by component.",
        "Scatter plot of first two PCs, coloured by salary_band.",
        "Run K-Means for k=2..6; compute silhouette score for each k.",
        "Plot silhouette scores vs k.",
        "For best k, compute adjusted Rand index between cluster labels and salary_band.",
        "Compare silhouette scores to reference values from shuffled (uniform random) data."
      ],
      "libraries": ["pandas", "sklearn", "matplotlib", "seaborn"]
    },
    "expected_outputs": [
      {"type": "plot", "filename": "pca_scree.png", "description": "PCA scree plot (explained variance per component)"},
      {"type": "plot", "filename": "pca_scatter.png", "description": "PCA scatter of first two components, coloured by salary_band"},
      {"type": "plot", "filename": "silhouette_scores.png", "description": "Silhouette score vs number of clusters"},
      {"type": "table", "description": "k, silhouette score, adjusted Rand index vs salary_band"}
    ],
    "validation": {
      "check": "If data is pure noise, PCA variance should be roughly uniform across components and silhouette scores should be low (< 0.25)."
    }
  },
  {
    "id": "EXP-11",
    "title": "Multiple-comparison correction (FDR)",
    "objective": "Apply Benjamini-Hochberg FDR correction to all p-values collected from previous experiments.",
    "hypotheses": ["H-09"],
    "input_artifacts": [],
    "depends_on": ["EXP-03", "EXP-04", "EXP-05", "EXP-07", "EXP-08", "EXP-09"],
    "method": {
      "steps": [
        "Collect all p-values from: Pearson correlations (EXP-03), Spearman correlations (EXP-04), Kruskal-Wallis (EXP-05), OLS F-test (EXP-07), permutation test (EXP-08), binomial test (EXP-09).",
        "Apply Benjamini-Hochberg procedure at alpha=0.05 using statsmodels.stats.multitest.multipletests.",
        "Report original p-values, adjusted p-values, and reject/fail-to-reject decisions.",
        "Summarize: count of tests that survive correction out of total tests."
      ],
      "libraries": ["statsmodels"]
    },
    "expected_outputs": [
      {"type": "table", "description": "Test ID, source experiment, original p-value, BH-adjusted p-value, reject null (yes/no)"}
    ],
    "validation": {
      "check": "Total number of p-values should equal the number of individual tests run. If zero survive, conclude no detectable signal in the dataset."
    }
  }
]
